\section{Supplemental Material}
Consider a degenerate optical parametric oscillator (OPO)
\cite{gardiner_zoller}. The equation of motion for the optical-mode
analytic signal is
\begin{align}
\diff{a(t)}{t} &= -\frac{\gamma}{2}a(t) -i\omega_m a(t) + 2\lambda a^*(t) + \sqrt{\gamma} A(t),
\end{align}
where $\gamma$ is the coupling rate, $\omega_m$ is the resonance
frequency, $\lambda$ is the pump coefficient, and $A(t)$ is the input
field. The output field is given by
\begin{align}
A_{\rm out}(t) &= \sqrt{\gamma} a(t) - A(t) + A'(t),
\end{align}
where $A'$ is an excess noise. Suppose that $A_{\rm out}$ is
measured by continuous heterodyne detection, and $A$ and $A'$ are
white phase-insensitive noises with noise powers $S_{\rm in}$ and
$S'$. After some lengthy but standard calculations, the
output power spectral density is given by
\begin{align}
S(\omega) &= [1+2V(\omega)]S_{\rm in} + S',
\end{align}
where $V(\omega)$ is the idler gain. In terms of normalized frequency
and parameters,
\begin{align}
V(\Omega) &= \frac{\Gamma^2}
{\Bk{\Omega^2 -\bk{g^{-2}-1-\Gamma^2/4}}^2+(g^{-2}-1)\Gamma^2},
\\
\Omega &\equiv \frac{\omega}{2|\lambda|},
\quad
g \equiv \frac{2|\lambda|}{\omega_m},
\quad
\Gamma \equiv \frac{\gamma}{2|\lambda|}.
\end{align}
To compute the Fisher information for estimating $\omega_m$
from $A_{\rm out}$, we start with the Bhattacharyya distance \cite{vantrees3}:
\begin{align}
B(g,g') &= 2|\lambda| t
\int_{-\infty}^{\infty} \frac{d\Omega}{2\pi} \ln \frac{S(\Omega|g)+S(\Omega|g')}
{2\sqrt{S(\Omega|g)S(\Omega|g')}},
\end{align}
and find the Fisher information through the identity \cite{vantrees3}:
\begin{align}
\mathcal G(\omega_m) &= 4 \bk{\parti{g}{\omega_m}}^2\partit{}{g} B(g,g')\Big|_{g' = g}.
\end{align}
If the noise powers are quantum-limited,
\begin{align}
S_{\rm in} &= S' = 0.5,
\\
S(\Omega) &= V(\Omega) + 1.
\end{align}
After more algebra, we get
\begin{align}
\mathcal G(\omega_m) &= \frac{8|\lambda|^3t}{\omega_m^4} \int_{-\infty}^{\infty} \frac{d\Omega}{2\pi}\bk{\parti{V}{g}}^2
\frac{1}{(V+1)^2}.
\end{align}
Focusing on the OPO threshold, which occurs at
\begin{align}
g &= \bk{1-\Gamma^2/4}^{-1/2},
\end{align}
we obtain
\begin{align}
\mathcal G &= 
\frac{16\omega_m^2t}{\gamma^3}
\int_{-\infty}^{\infty} \frac{dx}{2\pi} \frac{1}{ (x^2+1)^2}
\frac{1}{[1+\Gamma^2x^2(x^2+1)]^2}.
\end{align}
To obtain an analytic result, suppose $\Gamma < 2$, such that we can
lower-bound $\mathcal G$:
\begin{align}
\mathcal G &> \frac{16\omega_m^2t}{\gamma^3}
\int_{-\infty}^{\infty} \frac{dx}{2\pi} \frac{1}{ (x^2+1)^2}
\frac{1}{[1+4x^2(x^2+1)]^2} 
\nonumber\\
&= \frac{1.532\omega_m^2t}{\gamma^3}.
\end{align}
In the limit of $\Gamma \to 0$, on the other hand,
$\mathcal G \to 4\omega_m^2 t/\gamma^3$, so
\begin{align}
\frac{4\omega_m^2 t}{\gamma^3}> \mathcal G >
 \frac{1.532\omega_m^2t}{\gamma^3},
\quad
0 <  \Gamma < 2,
\end{align}
which is the result quoted in the main text. This result suggests
that the parameter estimation accuracy can be improved significantly
if $\gamma$ is reduced.

