\section{Appendix A:  Summary of results from finite-size Ising mean field theory}

\renewcommand{\theequation}{A\arabic{equation}}
\setcounter{equation}{0}  

\noindent The existence of finite-size scaling behavior follows from the large-deviation function, Eq.~\ref{fe}, of the order parameter distribution, Eq.~\ref{cw}. We will compare numerical estimates for the finite-size scaling behavior of noisy pitchfork bifurcations, based on standard Monte Carlo techniques~\cite{Binder:1986wu, Janke:1996tm, Janke:2002uc}, to mean-field predictions for the absolute value of the order parameter, $\langle\left\vert m \right\vert \rangle$, and the susceptibility, $\chi$, given by 
\begin{equation}{}
\chi\,\equiv\,N\left(\big\langle\left\vert m \right\vert^2 \big\rangle -\big\langle\left\vert m \right\vert \big\rangle^2\right).
\eeq{defs1}
When evaluated at the critical point, $\tilde{t}=0$, the mean-field observables depend only on  the system size, $N$, namely
\begin{subequations}
\begin{align}
\left.\big\langle\left\vert m \right\vert \big\rangle \right\vert_c&= \frac{1}{\Gamma\left(\frac{1}{4}\right)}\left(\frac{24 \pi^2}{N}\right)^{1/4}, \label{fssp:m} \\
\left.\chi\right\vert_c &=  \frac{4\pi}{\Gamma\left(\frac{1}{4}\right)^2}\left(1-\frac{1}{\sqrt{2}}\right)\sqrt{3N}.\label{fssp:chi} 
\end{align}
\label{fssp}
\end{subequations}
\hskip-0.1cm Near the critical point, expressions for observables can be calculated in closed form from the moments of Eq.~\ref{cw} and obey the finite-size scaling relationships
\begin{eqnarray}
\big\langle\left\vert m \right\vert \big\rangle&=& (N^{1/4})^{-\beta/\nu} G_{m}\left((N^{1/4})^{1/\nu}\tilde{t}\right), \nonumber \\
\chi &=& (N^{1/4})^{\gamma/\nu} G_{\chi}\left((N^{1/4})^{1/\nu}\tilde{t}\right), 
\eeqa{scp}
where $\nu=1/2$, $\beta=1/2$, and $\gamma=1$ are the mean-field critical exponents, and the $G_X$ are universal scaling functions.

\section*{Methods}

\subsection*{A) Weak Measurement of $\langle\hat{\Pi}_{I}\rangle_w$ and $\langle\hat{\Pi}_{II}\rangle_w$}

The weak measurement of $\langle\hat{\Pi}_{{I}}\rangle_{w}$ and $\langle\hat{\Pi}_{{II}}\rangle_{w}$ is performed using absorbers with a high transmissivity (i.e., a ``weak absorption"). Phenomenologically, an absorption in path $j$ can be represented by an imaginary optical potential \begin{align}
\hat{V}_{j}=-i\mu_{j}(r)\hat\Pi_{j},
\end{align} 
where the absorption coefficient is given by $\text{M}_j=\int \mu_j(r)\mathrm dr$ in path $j$ with $r$ is integrated on the absorber slab thickness. For weak absorption $\text{M}_{j}$ can be related to the transmissivity $T_{j}$ through $\text{M}_{j}\approx1-\sqrt{T_{j}}$ \cite{sears89}. Omitting for simplicity the free evolution operators in the following expressions, the wavefunction after the wavepacket has interacted with the absorber along path $j$ is
\begin{align}
|\psi'\rangle=\mathrm e^{-i\int\mathrm dr \hat{V}_{j}}|\psi_{i}\rangle\approx\left\lbrack1-\text{M}_{j}\hat\Pi_{j}+\cdots\right\rbrack|\psi_{i}\rangle
\end{align} 
for small $\text{M}_{j}$. Using $\langle\hat{\Pi}_{j}\rangle_{w}=\frac{\langle\psi_{f}|\hat{\Pi}_{j}|\psi_{i}\rangle}{\langle\psi_{f}|\psi_{i}\rangle}$ the intensity for the postselected outcome takes the form 
\begin{equation}
\text{I}_{\text{j}}^{\text{ABS}}=|\langle\psi_{f}|\psi_{i}\rangle|^{2}\left\lbrack1-2\text{M}_j\langle\hat{\Pi}_{{j}}\rangle_{w} \right\rbrac
\end{equation}
where contribution of the imaginary part of $\langle\hat{\Pi}_{j}\rangle_{w}$ is treated as being of order or less then $\text{M}^2$: This is justified by the contrast $C\le0.024(5)$ of the empty interferometer measurements with the experimental pre- and postselected states $|\psi_i\rangle$ and $|\psi_f\rangle$. Since $\text{I}^{\text{REF}}=|\langle\psi_{f}|\psi_{i}\rangle|^{2}$, the weak values can be extracted from the observation of $\text{I}_{{j}}^{\text{ABS}}/\text{I}^{\text{REF}}$.


\subsection*{B) Weak measurement of $\langle \hat{\sigma}_z\hat{\Pi}_{{I}}\rangle_w$ and $\langle \hat{\sigma}_z\hat{\Pi}_{{II}}\rangle_w$}

The weak value of $\hat{\sigma}_z\hat{\Pi}_{{j}}$ is determined using path conditioned spin rotations. To measure $\langle\hat{\sigma}_z\hat{\Pi}_{{j}}\rangle_w$, a small magnetic field is applied in path $j$. The interaction Hamiltonian for this measurement is
\begin{align}
\hat{H}_{j}=-\gamma\frac{\hat{\sigma}_z}{2}B_z\hat{\Pi}_j
\end{align}
where $\gamma$ is the gyromagnetic ratio and $B_z$ an externally applied magnetic field. $\hat{\Pi}_{j}$ denotes the fact the the magnetic field is applied only in the region along path $j$. $\vec{\sigma}$ is the Pauli vector; applying a magnetic field along $\hat{z}$ leads to the $\hat{\sigma}_{z}$ component of the Pauli matrix, which is the generator of rotations around the z-axis.

