\section{Spectral decomposition of the staggered magnetization and large deviation theory}
\label{sec:app}

The aim of this appendix is to outline the calculation of the joint probability distribution function $P(\varepsilon,m;t)$ that the system at time $t$ has energy density $\varepsilon$ and staggered magnetization $m$ using large deviation theory~\cite{Touchette2009lb}. This then directly leads to a computational scheme for the calculation of the energy-resolved staggered magnetization $\mathcal{M}_{s}(\varepsilon,t)$. The joint probability distribution $P(\varepsilon,m;t)$ is defined as:
\begin{equation}
	P(\varepsilon,m;t)  = \sum_\nu |\langle E_v |\psi_0(t)\rangle|^2 \delta(\varepsilon-e_\nu)\delta(m_{\nu} - m)
\end{equation}
where $e_\nu = E_\nu/N$ is the energy density and $m_{\nu}$ is the staggered magnetization of the state $|E_\nu\rangle$: $H_{\Delta_0}|E_\nu\rangle = N e_\nu |E_\nu\rangle$ and $\mathcal{M}_{s}|E_\nu\rangle = m_\nu |E_\nu\rangle$. The function
\begin{align}
	G(s,\mu;t) = \sum_\nu |\langle E_v |\psi_0(t)\rangle|^2 e^{-s E_\nu} e^{-\mu N m_\nu} \nonumber \\
	= \langle \psi_0(t) | e^{-s H_{\Delta_0}} e^{-\mu N\mathcal{M}_{s}} |\psi_0(t)\rangle
\end{align}
is related to $P(\varepsilon,m;t)$ via
\begin{equation}
	G(s,\mu;t) = \int d\varepsilon \int dm P(\varepsilon,m;t) e^{-N\varepsilon s} e^{-N m \mu}.
\end{equation}
The generating function $G(s,\mu;t)$ obeys a large-deviation scaling~\cite{Heyl2013a}:
\begin{equation}
	G = e^{N g(s,\mu;t)}
\end{equation}
with $g(s,\mu;t)$ an intensive function independent of system size $N$.

samples.second_piece:
As a consequence of this large deviation scaling the joint distribution function has to be of the following structure~\cite{Touchette2009lb}
\begin{equation}
	P(\varepsilon,m;t) = e^{-N\theta(\varepsilon,m;t)}
\end{equation}
with the rate function $\theta(\varepsilon,m;t)$ again intensive and given by the following series of Legendre transforms:
\begin{align}
	\theta(\varepsilon,m;t) = -\inf_{\mu} \left[ \mu m + \varphi(\varepsilon,\mu;t) \right], \nonumber \\
	\varphi(\varepsilon,\mu;t) = \inf_{s} \left[ \varepsilon s + g(s,\mu;t) \right].
\end{align}
The corresponding back transformations read:
\begin{align}
	\varphi(\varepsilon,\mu;t) = -\inf_{m} \left[ \mu m +\theta(\varepsilon,m;t) \right] ,\nonumber \\
	g(s,\mu;t) = -\inf_{\varepsilon} \left[ \varepsilon s - \varphi(\varepsilon,\mu;t) \right].
\end{align}
As in thermodynamics the Legendre transform of $\theta(\varepsilon,m;t)$, for example, can be calculated by:
\begin{equation}
	\varphi(\varepsilon,\mu;t) = - \mu m(\varepsilon,\mu;t) - \theta(\varepsilon, m(\varepsilon,\mu;t) ;t)
\end{equation}
with $m(\varepsilon,\mu;t)$ solving the ``equation of state'':
\begin{equation}
	 \mu = - \frac{d\theta(\varepsilon,m;t)}{dm}.
\end{equation}
Provided $g(s,\mu;t)$ is differentiable with respect to $s$ and $\mu$ it can be shown that $P(\varepsilon,m;t)$ obeys a central-limit theorem~\cite{Touchette2009lb} which is used in the main text to derive the energy-resolved observables. In order to obtain the energy-resolved staggered magnetization $\mathcal{M}_{s}(\varepsilon,t)$ it is necessary to determine the infimum of $\theta(\varepsilon,m;t)$ over all $m$ which according to the previous formulas is
\begin{equation}
	\varphi(\varepsilon,0;t) = -\inf_m \left[ \theta(\varepsilon,m;t)\right].
\end{equation}
Thus, the infimum happens at $\mu=0$ such that from the equation of state
\begin{align}
	m^\ast(\varepsilon,t) =- \left. \frac{\partial \varphi(\varepsilon,\mu;t)}{\partial\mu} \right|_{\mu=0} = -\left. \frac{\partial g}{\partial\mu} \right|_{s=s(\varepsilon,\mu;t),\mu=0} \nonumber \\
	= \left. \langle \psi_0(t,s) | \mathcal{M}_{s}(t) |\psi_0(t,s) \rangle\right|_{s=s(\varepsilon,\mu=0;t)}  ,
\end{align}
with
\begin{align}
	|\psi_0(t,s)\rangle = \frac{e^{-s H_{\Delta_0}/2}}{\sqrt{\mathcal{N}}} |\psi_0(t)\rangle,\nonumber \\
	\mathcal{N} = \langle \psi_0(t) | e^{-sH_{\Delta_0}} |\psi_0(t) \rangle,
\end{align}
and $s=s(\varepsilon,\mu=0,t)$ solves the equation of state
\begin{equation}
	\varepsilon = \frac{1}{N} \langle \psi_0(t,s) | H_{\Delta_0} | \psi_0(t,s) \rangle.
\end{equation}
This yields the formulas presented in the main text.



\end{document}

