\begin{eqnarray}\label{compacteomsup3}
\nonumber
P(\bm{\mathcal{F}}_{\tau}(t)=\textbf{A}) &=& 
\dfrac{1}{(2 \pi)^d}   \int_{\textbf{k}}  \exp \left(-\dfrac{1}{2 \tau^2} \int_0^\tau k^2 dt + i \textbf{k} \cdot \textbf{A} \right)\\
&=&\dfrac{1}{(2 \pi)^d}   \int_{\textbf{k}}  \exp \left(-\dfrac{k^2}{2 \tau} + i \textbf{k} \cdot \textbf{A} \right).
\end{eqnarray}
RHS of above equation is just Inverse Fourier Transform of a Gaussian function $ \exp-k^2 /2 \tau$, therefore the probability density for $\bm{\mathcal{F}}_{\tau}(t)$ becomes
\begin{eqnarray}\label{compacteomsup3}
P(\bm{\mathcal{F}}_{\tau}(t)=\textbf{A}) 
=\left(\dfrac{\tau}{2 \pi}\right)^{d/2}  \exp \left(-\dfrac{\tau A^2}{2} \right).
\end{eqnarray}
From Jacobian transformation the probability density for ${\bf V}_\tau(t)$ is
\begin{eqnarray}\label{compacteomsup4}
P({\bf V}_\tau(t))=\mbox{det} \left( \dfrac{\partial \bm{ \mathcal{F} }_\tau}{\partial {\bf V}_\tau}\right) P(\bm{\mathcal{F}}_{\tau}(t)).  
\end{eqnarray}
But from Eq. \eqref{compacteomsup1} 
\begin{equation}\label{22}
