\end{eqnarray}
Since $\bm{\Pi}^T \bm{\Pi}=(2\bsf{D})^{-1}$,
\begin{eqnarray}\label{33}
\nonumber
\mbox{det}\bm{\Pi}&=&(\mbox{det}({2\bsf{D}}^{-1}))^{1/2}\\
\nonumber
&=&2^{-d/2}({\mbox{det}{\bsf{D}})}^{-1/2}
\end{eqnarray}
and 
\begin{eqnarray}\label{compacteomsup6}
\nonumber
&&\left(\bm{\Pi} \cdot {\bf V} - \bm{\mathcal{S}}_\tau(t)\right)^2\\
\nonumber
&&=\left(\bm{\Pi} \cdot {\bf V}- \bm{\mathcal{S}}_\tau(t) \right)^T \left(\bm{\Pi} \cdot {\bf V}- \bm{\mathcal{S}}_\tau(t)\right)\\
\nonumber
&&=\left(  {\bf V}-\bm{\Pi}^{-1} \cdot \bm{\mathcal{S}}_\tau(t) \right)^T \bm{\Pi}^T \bm{\Pi} \left(  {\bf V}- \bm{\Pi}^{-1} \bm{\mathcal{S}}_\tau(t)\right)\\
&&=\frac{1}{2}\left(  {\bf V}-\bm{\Pi}^{-1} \cdot \bm{\mathcal{S}}_\tau(t) \right)^T {\bsf{D}}^{-1} \left(  {\bf V}- \bm{\Pi}^{-1} \bm{\mathcal{S}}_\tau(t)\right).
\end{eqnarray}
Eq. \eqref{compacteomsup5} then becomes
\begin{eqnarray}\label{compacteomsup7}
\nonumber
