\paragraph {Norms.}
Denote the maximum absolute element of a matrix $A\in \mathbb{C}^{N\times N}$ with
$
\Vert A \Vert_{\max}:= \max_{j,k} |A_{jk}|.
$
The Frobenius or Hilbert-Schmidt norm is given by 
$
\Vert A \Vert_{F}:= \sqrt{\sum_{j,k} |A_{jk}|^2 }
$
and its nuclear norm by
$
\Vert A \Vert_\ast := \sum_{i=1}^r \sigma_i,
$
where $r$ is the rank and $\sigma_j$ are the singular values.


\paragraph{Modified swap matrix.}
The modified swap matrix is defined as
\begin{equation}
S_A=\sum_{ j, k=1}^N A_{jk} |k\rangle \langle j| \otimes | j \rangle \langle k | \in\mathbb{C}^{N^2 \times N^2}.
\end{equation}
Taking $A_{jk}\to 1$ leads to the original swap matrix 
$
S=\sum_{ j, k=1}^N |k\rangle \langle j| \otimes | j \rangle \langle k | \in\mathbb{C}^{N^2 \times N^2}.
$
The $N^2$ eigenvalues of $S_A$ are 
\begin{equation}
A_{11}, A_{22},\hdots,A_{NN}, A_{12},-A_{12},\hdots,A_{j,k>j},-A_{j,k>j},\hdots,
\end{equation}
where $k>j$ denotes an index $k$ greater than $j$. The maximal absolute eigenvalue of $S_A$ is thus $\max_{j,k} |A_{jk}|\equiv \Vert A \Vert_{\max}$, corresponding to the maximal absolute matrix element of $A$. The square of the modified swap matrix is
\begin{eqnarray}\label{eqSwapSquare}
(S_A)^2&=&\sum_{ j, k=1}^N |A_{jk}|^2\, |k\rangle \langle k| \otimes | j \rangle \langle j | \leq \Vert A \Vert_{\max}^2 \,\mathbbm{1}.
\end{eqnarray}
Its eigenvalues are $|A_{jk}|^2$ and the maximal eigenvalue is $\Vert A \Vert_{\max}^2$. This already points to the result that the second order error of our method naturally scales with  $\Vert A \Vert_{\max}^2$, which we will now derive.

\paragraph{Error analysis.}
In the following, we  estimate the error from the second-order term in $\Delta t$ in the expansion Eq.~(\ref{eqMainExpansion}). The nuclear norm of the operator part of the second order error is
\begin{eqnarray}\label{eq:error1}
\epsilon_{\rho,\sigma} = \Vert {\rm tr}_1 \{ S_A\ \rho \otimes \sigma \ S_A \} &-&\frac{1}{2} {\rm tr}_1 \{ (S_A)^2\ \rho \otimes \sigma \} \\ &-& \frac{1}{2}{\rm tr}_1 \{  \rho \otimes \sigma\ (S_A)^2 \} \Vert_\ast. \nonumber
\end{eqnarray}
In Ref.~\cite{Lloyd2014}, this error was equal to 
$\epsilon_{\rho,\sigma}^{\rm qPCA} = \Vert \rho - \sigma \Vert_\ast \leq 2$, 
which is achieved in the present algorithm by choosing $A$ such that $A_{jk}=1$ for each $j,k$. Here, our algorithm coincides with the qPCA method for $\rho$ chosen as the uniform superposition. For general low-rank $A$, we bound Eq.~\eqref{eq:error1} via the triangle inequality. Taking the nuclear norm of the first term results in
\begin{align}
\Vert {\rm tr}_1 \{ S_A \rho \otimes \sigma S_A \} \Vert_\ast \leq &  \Vert   S_A \rho \otimes \sigma S_A \Vert_\ast \nonumber \\
\leq&\Vert  \rho \otimes \sigma  \Vert_\ast \Vert S_A^2 \Vert_\ast \leq  \Vert A\Vert_{\max}^2.
\end{align}
The second and third term can be treated similarly. We obtain $\Vert {\rm tr}_1 \{ (S_A)^2 \rho \otimes \sigma \} \Vert_\ast \leq  \Vert A\Vert_{\max}^2$.

