\section{Derivation of Eq.\ (12).}

We can write any input state to the first port as $|\Psi'\>_{A^{({\rm in})}\tilde{A}^{({\rm in})}}=(I_{A^{({\rm in})}}\otimes X)|\Phi^+\>_{A^{({\rm in})}\tilde{A}^{({\rm in})}}$, where $X$ is a matrix constrained by $\operatorname{Tr} X^\dag X=d_{A^{({\rm in})}}=2$ and $I_{A^{({\rm in})}}$ is the identity matrix on $A^{({\rm in})}$. Since the ancillary system is in the maximally mixed state $\pi_{A^{({\rm anc})}}:=I_{A^{({\rm anc})}}/d_{A^{({\rm anc})}}$ with $d_{A^{({\rm anc})}}=D/2$, we first consider its purification $\Phi^+_{A^{({\rm anc})}\tilde{A}^{({\rm anc})}}$ and trace out $\tilde{A}^{({\rm anc})}$ in the end. The output state is thus 
\begin{align*}
\Phi_{\map{N}_{\theta}\ast\Psi}=&\int{\rm d} U\,\left(\map{U}_{A^{({\rm in})}A^{({\rm anc})}}\map{V}_{\theta,A^{({\rm in})}}\otimes\map{X}_{\tilde{A}^{({\rm in})}}\otimes\operatorname{Tr}_{\tilde{A}^{({\rm anc})}}\otimes\ \map{U}^\dag_{B^{({\rm in})}}\otimes\map{I}_{\tilde{B}^{({\rm in})}}\right)\left(\Phi^+_{(A^{({\rm in})}A^{({\rm anc})})(\tilde{A}^{({\rm in})}\tilde{A}^{({\rm anc})})}\otimes\Phi^+_{B^{({\rm in})}\tilde{B}^{({\rm in})}}\right),
\end{align*}
where $\Phi^+_{(A^{({\rm in})}A^{({\rm anc})})(\tilde{A}^{({\rm in})}\tilde{A}^{({\rm anc})})}$ denotes the maximally entangled state between the product systems $A^{({\rm in})}A^{({\rm anc})}$ and $\tilde{A}^{({\rm in})}\tilde{A}^{({\rm anc})}$ and $\operatorname{Tr}_{\tilde{A}^{({\rm anc})}}$ denotes the partial trace operation. Using the elementary property 
\begin{align}\label{trivial}
(Y\otimes I)|\Phi^+\>=(I\otimes Y^T)|\Phi^+\>
\end{align}
that holds for any matrix $Y$, the output state can be rewritten as
\begin{align}
\Phi_{\map{N}_{\theta}\ast\Psi}&=\int{\rm d} U\,\left(\map{U}_{A^{({\rm in})}A^{({\rm anc})}}\map{V}_{\theta,A^{({\rm in})}}\otimes\map{X}_{\tilde{A}^{({\rm in})}}\otimes\operatorname{Tr}_{\tilde{A}^{({\rm anc})}}\otimes\ \map{I}_{B^{({\rm in})}}\otimes\map{\bar{U}}_{\tilde{B}^{({\rm in})}}\right)\left(\Phi^+_{(A^{({\rm in})}A^{({\rm anc})})(\tilde{A}^{({\rm in})}\tilde{A}^{({\rm anc})})}\otimes\Phi^+_{B^{({\rm in})}\tilde{B}^{({\rm in})}}\right)\nonumber\\
&=\left(\map{T}_{(A^{({\rm in})}A^{({\rm anc})})\tilde{B}^{({\rm in})}}\otimes\map{X}_{\tilde{A}^{({\rm in})}}\map{V}_{\theta,\tilde{A}^{({\rm in})}}^T\otimes\operatorname{Tr}_{\tilde{A}^{({\rm anc})}}\otimes\ \map{I}_{B^{({\rm in})}}\right)\left(\Phi^+_{(A^{({\rm in})}A^{({\rm anc})})(\tilde{A}^{({\rm in})}\tilde{A}^{({\rm anc})})}\otimes\Phi^+_{B^{({\rm in})}\tilde{B}^{({\rm in})}}\right),\label{output-inter}
\end{align}
where $\map{T}$ is a twirling channel $\map{T}(\rho):=\int{\rm d} U\,\left(U\otimes \bar{U}\right)\rho\left(\bar{U}\otimes U\right)$ and $\bar{U}$ denotes the conjugate of $U$. By Schur's lemma \cite{fulton2013representation}, the output of the twirling channel is of the form $\map{T}(\rho)=\operatorname{Tr}[\Phi^+ \rho]\Phi^++\operatorname{Tr}[(I-\Phi^+)\rho]\pi^-$, 
where $\pi^-:=\frac{1}{D^2-1}(I-\Phi^+)$ for a $(D\otimes D)$ bipartite system. Then we obtain the action of the twirling $\map{T}_{(A^{({\rm in})}A^{({\rm anc})})\tilde{B}^{({\rm in})}}$ on $\Phi^+_{(A^{({\rm in})}A^{({\rm anc})})(\tilde{A}^{({\rm in})}\tilde{A}^{({\rm anc})})}\otimes\Phi^+_{B^{({\rm in})}\tilde{B}^{({\rm in})}}$ as
\begin{align}
&\left(\map{T}_{(A^{({\rm in})}A^{({\rm anc})})\tilde{B}^{({\rm in})}}\otimes\map{I}_{\tilde{A}^{({\rm in})}\tilde{A}^{({\rm anc})}B^{({\rm in})}}\right)\left(\Phi^+_{(A^{({\rm in})}A^{({\rm anc})})(\tilde{A}^{({\rm in})}\tilde{A}^{({\rm anc})})}\otimes\Phi^+_{B^{({\rm in})}\tilde{B}^{({\rm in})}}\right)\nonumber\\
=&\frac{1}{D^2}\left(\Phi^+_{(A^{({\rm in})}A^{({\rm anc})})\tilde{B}^{({\rm in})}}\otimes\Phi^+_{(\tilde{A}^{({\rm in})}\tilde{A}^{({\rm anc})})B^{({\rm in})}}\right)+\left(\frac{D^2-1}{D^2}\right)\left(\pi^-_{(A^{({\rm in})}A^{({\rm anc})})\tilde{B}^{({\rm in})}}\otimes\pi^{-}_{(\tilde{A}^{({\rm in})}\tilde{A}^{({\rm anc})})B^{({\rm in})}}\right).\label{twirling}
\end{align}
Operationally, this twirling $\map{T}_{(A^{({\rm in})}A^{({\rm anc})})\tilde{B}^{({\rm in})}}$  swaps the entanglement with $A^{({\rm in})}A^{({\rm anc})}$ from $\tilde{A}^{({\rm in})}\tilde{A}^{({\rm anc})}$ to $\tilde{B}^{({\rm in})}$ with a success probability $1/D^2$, by performing correlated random unitaries. Now, we consider the action of the partial trace $\operatorname{Tr}_{\tilde{A}^{({\rm anc})}}$ operation on the state in Eq.\ (\ref{twirling}).

samples.second_piece:
Note that $B^{({\rm in})}$ is isomorphic to $B^{({\rm in},1)}\otimes B^{({\rm in,2})}$ with $B^{({\rm in},1)}\simeq\tilde{A}^{({\rm in})}$ and $B^{({\rm in},2)}\simeq\tilde{A}^{({\rm anc})}$, $\operatorname{Tr}_{\tilde{A}^{({\rm anc})}}\Phi^+_{(\tilde{A}^{({\rm in})}\tilde{A}^{({\rm anc})})B^{({\rm in})}}=\Phi^+_{\tilde{A}^{({\rm in})}B^{({\rm in},1)}}\otimes\pi_{B^{({\rm in},2)}}$, and $\operatorname{Tr}_{\tilde{A}^{({\rm anc})}}\pi^-_{(\tilde{A}^{({\rm in})}\tilde{A}^{({\rm anc})})B^{({\rm in})}}=(D^2-1)^{-1}((D^2/4)I-\Phi^+)_{\tilde{A}^{({\rm in})}B^{({\rm in},1)}}\otimes\pi_{B^{({\rm in},2)}}$. With this and substituting Eq.\ (\ref{twirling}) into Eq.\ (\ref{output-inter}), we obtain the output state as
\begin{align}
\Phi_{\map{N}_{\theta}\ast\Psi}&=\frac{1}{D^2}\Phi^+_{(A^{({\rm in})}A^{({\rm anc})})\tilde{B}^{({\rm in})}}\otimes\left(\map{X}_{\tilde{A}^{({\rm in})}}\map{V}_{\theta,\tilde{A}^{({\rm in})}}^T\otimes\map{I}_{B^{({\rm in},1)}}\right)\left(\Phi^+_{\tilde{A}^{({\rm in})}B^{({\rm in,1})}}\right)\otimes\pi_{B^{({\rm in},2)}}\nonumber\\
&\qquad+\frac{1}{D^2}\pi^-_{(A^{({\rm in})}A^{({\rm anc})})\tilde{B}^{({\rm in})}}\otimes\left(\map{X}_{\tilde{A}^{({\rm in})}}\map{V}_{\theta,\tilde{A}^{({\rm in})}}^T\otimes\map{I}_{B^{({\rm in},1)}}\right)\left(\frac{D^2}{4}I_{\tilde{A}^{({\rm in})}B^{({\rm in},1)}}-\Phi^+_{\tilde{A}^{({\rm in})}B^{({\rm in},1)}}\right)\otimes\pi_{B^{({\rm in},2)}}\nonumber\\
&=\frac{1}{D^2}(\Psi_\theta)_{B^{({\rm in},1)}\tilde{A}^{({\rm in})}}\otimes\Phi^+_{(A^{({\rm in})}A^{({\rm anc})})\tilde{B}^{({\rm in})}}\otimes\pi_{B^{({\rm in},2)}}\nonumber\\
&\qquad+\frac{1}{D^2}\left(\frac{D^2-4}{4}(I\otimes XX^\dag)+3\pi^-_{\theta,\Psi'}\right)_{\tilde{A}^{({\rm in})}B^{({\rm in},1)}}\otimes\pi^-_{(A^{({\rm in})}A^{({\rm anc})})\tilde{B}^{({\rm in})}}\otimes\pi_{B^{({\rm in},2)}}\nonumber
\end{align}
having used Eq.\ (\ref{trivial}), $d_{A^{({\rm in})}}=2$, and the relation $|\Psi'\>_{B^{({\rm in})}\tilde{A}^{({\rm in})}}=(I_{B^{({\rm in})}}\otimes X)|\Phi^+\>_{B^{({\rm in})}\tilde{A}^{({\rm in})}}$ in the last step. Here $\pi^-_{\theta,\Psi'}:=(I\otimes X)(I\otimes I-\Phi^+_\theta)(I\otimes X^\dag)/3$ is a quantum state. Finally, using $XX^\dag/2=\operatorname{Tr}_{B^{({\rm in,1})}}\Psi'$ we get Eq.\ (12).


\end{widetext}



