\section{Introduction}

The Edwards model \cite{Edwards} for self-repelling or "weakly
self-avoiding" $d$-dimensional Brownian motion, with applications in polymer
physics and quantum field theory, is informally given by a Gibbs factor 
\begin{equation*}
G=\frac{1}{Z}\exp \left( -g\int_{0}^{T}ds\int_{0}^{t}dt\delta \left(
B(s)-B(t)\text{ }\right) \right) 
\end{equation*
with $g>0$ and$\ \ $ 
\begin{equation*}
Z=E\left( \exp \left( -g\int_{0}^{T}ds\int_{0}^{t}dt\delta \left( B(s)-B(t
\text{ }\right) \right) \right) .
\end{equation*
Usin
\begin{equation*}
\delta _{\varepsilon }(x):=\frac{1}{(2\pi \varepsilon )^{d/2}}e^{-\frac
|x|^{2}}{2\varepsilon }},\quad \varepsilon >0,
\end{equation*
one defines an approximate self-intersection local time by 
\begin{equation*}
L_{\varepsilon }:=\int_{0}^{T}dt\int_{0}^{t}ds\,\delta _{\varepsilon
}(B(t)-B(s)).
\end{equation*
For $d\geq 2
\begin{equation*}
\lim_{\varepsilon \searrow 0}\mathbb{E}(L_{\varepsilon })=\infty .
\end{equation*
For the planar case $d=2,$ Varadhan \cite{v} has shown that centering 
\begin{equation*}
L_{\varepsilon ,c}\ :=L_{\varepsilon }\ -\mathbb{E}(L_{\varepsilon })\ \text
and}\ L_{c}:=\lim_{\varepsilon \searrow 0}L_{\varepsilon ,c}
\end{equation*
is sufficient to make the Gibbs factor $G=Z^{-1}\exp \left( -gL_{c}\right) $
well defined. An estimate for the rate of convergenc
\begin{equation*}
\Vert L_{c}\ -L_{\varepsilon ,c}\Vert _{2\ }^{2}\leq const.\varepsilon
^{\alpha }
\end{equation*
\ for all $\alpha <1/2$, is in Varadhan's words, "the most difficult step of
all and requires considerable estimation". In this note we shall use a
multiple Wiener integral or chaos expansion for an alternate and
comparatively straightforward argument, extending the estimate to all 
\alpha <1$.

\section{Fock space representation of the local time}

\label{Section1}

The Ito-Segal-Wiener isomorphism relates the $L^{2}\,$\ space of planar
Brownian motion with the Fock spac
\begin{equation*}
\mathfrak{F}=\left( \bigoplus_{n=0}^{\infty }\mathrm{Sym}\,L^{2}(\mathbb{R
^{n},n!d^{n}x)\right) ^{\otimes 2}.
\end{equation*
We shall use the multi-index notation 
\begin{equation*}
\mathbf{n}=(n_{1},n_{2})\ \quad n=n_{1}+n_{2},\quad \mathbf{n}!=n_{1}!n_{2}!
\end{equation*
The Fock space norm is the
\begin{equation*}
\Vert F\Vert _{2}^{2}=\sum_{n_{i}\geq 0}\mathbf{n}!\left\Vert F_{\mathbf{n
}\right\Vert _{2}^{2}.
\end{equation*}
For $L_{\varepsilon ,c}$ the kernel functions $F_{\mathbf{n}}$ were
computed explicitly in \cite{fhsw}. For the planar case the result is

\begin{proposition}
\cite{fhsw}: For $d=2$ the kernel functions $F_{\mathbf{n}}$ of 
$L_{\varepsilon ,c}(T)$ and $L_{c}(T)$ have their support on $\left[ 0,T\right] ^{n}$ 
and are, with $\varepsilon >0$, and $\varepsilon =0$ respectively, for $n>1$ 
\begin{align*}
& F_{2\mathbf{n},\varepsilon }(u_{1},\ldots ,u_{2n})=\frac{1}{2\pi }\left( 
\frac{1}{2}\right) ^{n}\frac{1}{n(n-1)\,\mathbf{n!}} \\
& \times \left( \frac{1}{(T+\varepsilon )^{n-1}}-\frac{1}{(v+\varepsilon
)^{n-1}}-\frac{1}{(T-u+\varepsilon )^{n-1}}+\frac{1}{(v-u+\varepsilon )^{n-1
}\right) ,
\end{align*
where $v:=\max_{1\leq k\leq 2n}u_{k}\leq T$ and $u:=\min_{1\leq k\leq 2n}u_{k}\geq 0$. For $n=1$
\begin{equation*}
F_{2,\varepsilon }(u_{1},u_{2})=-\frac{1}{4\pi }\left( \ln (v+\varepsilon
)+\ln (T-u+\varepsilon )-\ln (v-u+\varepsilon )-\ln (T+\varepsilon )\right) .
\end{equation*
All kernel functions $F_{\mathbf{n}}$ with odd $n_{i}$ are zero.
\end{proposition}

\subsection{The rate of convergence}

\label{Section2}

\begin{theorem}
\label{ratetrunc} Given $T>0$. Then for any $\alpha <1$ there is a constant 
C_{T,\alpha }>0$ such that for all $\varepsilon >0$ 
\begin{equation*}
\Vert L_{\varepsilon ,c}(T)-L_{c}(T)\Vert _{2}^{2}\leq C_{T,\alpha
}\varepsilon ^{\alpha }.
\end{equation*}
\end{theorem}

\noindent \textbf{Proof:} From Proposition 1 
\begin{equation*}
\left\Vert F_{2\mathbf{n},0}-F_{2\mathbf{n},\varepsilon }\right\Vert
_{2}^{2}=\Big(n(n-1)2\pi 2^{n}\mathbf{n}!\Big)^{-2
\int_{0}^{T}d^{2n}u_{k}K_{\varepsilon }^{2}(u,v,T)
\end{equation*
where for $n>1
