We can introduce the annhilation operator $\psi_{j,\boldsymbol{R}}$ for the $j$th Wannier function at site $\boldsymbol{R}$, and group $\{\psi_{j,\boldsymbol{R}}\}$ for $j=1,2,\dots,d$ into a column vector as $\boldsymbol{\psi}_{\boldsymbol{R}}$, and introduce $\boldsymbol{\psi}^\dagger_{\boldsymbol{R}}$ as the corresponding creation operators (in row vectors). Thus, we obtained a space-time crystal described by the following tight-binding Hamiltonian
\begin{equation}
    H = \sum_{\boldsymbol{R}',\boldsymbol{R}}\boldsymbol{\psi}_{\boldsymbol{R}'}^\dagger\left[\tilde{h}^{0}(\boldsymbol{R}'- \boldsymbol{R}) + \sum_{n\neq0} e^{in (\delta \boldsymbol{k} \cdot \boldsymbol{R}' - \Omega t)} \tilde{h}^{n}(\boldsymbol{R}'- \boldsymbol{R})\right]\boldsymbol{\psi}_{\boldsymbol{R}}.
    \label{eq:H_tight_binding}
\end{equation}

For periodic boundary condition, we can write $\boldsymbol{\psi}_{\boldsymbol{R}} = 1/\sqrt{N}\sum_{\boldsymbol{k}} e^{i\boldsymbol{k}\cdot\boldsymbol{R}} \boldsymbol{a}_{\boldsymbol{k}}$ and $\tilde{h}^{n}(\boldsymbol{R}) = 1/N \sum_{\boldsymbol{q}}e^{i\boldsymbol{q}\cdot\boldsymbol{R}} h_n(\boldsymbol{q})$, then we have 
\begin{equation}
    H  = \sum_{\boldsymbol{k}}\left[ \boldsymbol{a}^\dagger_{\boldsymbol{k}} h_0(\boldsymbol{k}) \boldsymbol{a}_{\boldsymbol{k}} 
    + \sum_{n\neq 0} \boldsymbol{a}^\dagger_{\boldsymbol{k}+n\delta\boldsymbol{k}} h_n(\boldsymbol{k}) \boldsymbol{a}_{\boldsymbol{k}} e^{-in\Omega t} \right].
\end{equation}

The operator $K(t) = H(t) - i\partial_t$ can be Block diagonalized if we introduce $\boldsymbol{A}_{\boldsymbol{k}}(t) = (\dots, e^{i\Omega t} \boldsymbol{a}_{\boldsymbol{k}-\delta\boldsymbol{k}}^T, \boldsymbol{a}_{\boldsymbol{k}}^T,e^{-i\Omega t}\boldsymbol{a}_{\boldsymbol{k}+\delta\boldsymbol{k}}^T,\dots)^T$. This leads to 
\begin{equation}
    K(t) =  \sum_{\boldsymbol{k}} \boldsymbol{A}_{\boldsymbol{k}}^\dagger(t) \left[\mathscr{H}(\delta\boldsymbol{k},\boldsymbol{k}) - i\partial_t\right] \boldsymbol{A}_{\boldsymbol{k}}(t),
\end{equation}
where we obtain the effective enlarged \emph{time-independent} Hamiltonian $\mathscr{H}(\boldsymbol{k})$, which we have derived using the Bloch functions in the main text. 

\subsection{Particle-hole symmetries in $\mathscr{H}(k)$}
In the main text, we have shown that the effective Hamiltonian $\mathscr{H}_{\rm eff}(k)$ for the 1D model proposed in class D has a particle-hole symmetry realized via $\rho_x \mathscr{H}_{\rm eff}(k) \rho_x = -\mathscr{H}_{\rm eff}(\pi - \delta k -k)^*$. Here, we generalize this result by showing that any truncation of the frequency-domain-enlarged Hamiltonian $\mathscr{H}(k)$ has a particle-hole symmetry with respect to the energy, say $-\Omega/2$, as long as the truncation is symmetric about this energy. To make a truncation symmetric around $-\Omega/2$, we write
\begin{equation}
    \mathscr{H}(k)\simeq\mathscr{H}_{N}(k)-\mathbb{I}\Omega/2
\end{equation}
where the $2N$-by-$2N$ matrix
\begin{equation}
\mathscr{H}_{N}(k)=\left(\begin{array}{cccc}
h_{0}(k-(N-1)\delta k)+(N-\frac{1}{2})\Omega & h_{1}^{\dagger}(k-(N-1)\delta k)\\
h_{1}(k-(N-1)\delta k) & \ddots & \ddots\\
