 &  & h_{1}(k+(N-1)\delta k) & h_{0}(k+N\delta k)-(N-\frac{1}{2})\Omega
\end{array}\right)
\end{equation}
and $\mathbb{I}$ is the identity matrix of the same size of $\mathscr{H}_{N}(k)$. For $h_0(k) = -2w\cos(ka)$ and $h_1(k) = \Delta \cos(ka+\delta k a/2)$, one can easily verify that $\mathscr{H}_N(k)$ has a particle-hole symmetry realized via $X_N \mathscr{H}_N(k) X_N = -\mathscr{H}_N(\pi - \delta k - k)^*$, with the $2N$ by $2N$ matrix
\begin{equation}
    X_{N}=\left(\begin{array}{ccc}
